let body = $json.body ?? $json;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { body = null; }
}
const missing = [];
const invalid = [];
const blank = (v) => v === undefined || v === null || (typeof v === 'string' && v.trim() === '');
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return { validation_result: 'invalid_structure', missing_fields: [], invalid_fields: [{ field: 'body', message: 'Debe ser un objeto JSON' }] };
}
const order = body.order;
if (!order || typeof order !== 'object' || Array.isArray(order)) {
  return { validation_result: 'invalid_structure', event_id: body.event_id || null, missing_fields: [], invalid_fields: [{ field: 'order', message: 'Falta el objeto order' }] };
}
for (const [path, value] of [['event_id', body.event_id], ['order.id', order.id], ['order.previous_status', order.previous_status], ['order.status', order.status], ['order.changed_at', order.changed_at], ['order.change_source', order.change_source]]) {
  if (blank(value)) missing.push(path);
}
if (body.event_type !== 'order.status_changed') invalid.push({ field: 'event_type', message: 'Debe ser order.status_changed' });
if (!blank(body.timestamp) && Number.isNaN(Date.parse(body.timestamp))) invalid.push({ field: 'timestamp', message: 'Fecha no válida' });
if (!blank(order.changed_at) && Number.isNaN(Date.parse(order.changed_at))) invalid.push({ field: 'order.changed_at', message: 'Fecha no válida' });
const validation_result = missing.length ? 'missing_fields' : invalid.length ? 'invalid_values' : 'valid';
return {
  validation_result, missing_fields: missing, invalid_fields: invalid,
  event_id: blank(body.event_id) ? null : String(body.event_id),
  order_id: blank(order.id) ? null : String(order.id),
  previous_status: blank(order.previous_status) ? null : String(order.previous_status),
  order_status: blank(order.status) ? null : String(order.status),
  changed_at: blank(order.changed_at) ? null : new Date(order.changed_at).toISOString(),
  change_source: blank(order.change_source) ? null : String(order.change_source)
};

const v = $('Validar cambio de estado').first().json;
const status = $json.integration_status;
const retry = status === 'pending_sync';
return {
  http_status: retry ? 503 : 200,
  response_body: {
    success: !retry, event_id: v.event_id, order_id: v.order_id,
    previous_status: v.previous_status, order_status: v.order_status,
    integration_status: status,
    message: retry ? 'El pedido aún no existe en el back-office; se reintentará' : status === 'already_processed' ? 'Evento ya procesado' : 'Estado actualizado correctamente'
  }
};

return {
  http_status: 400,
  response_body: {
    success: false,
    event_id: $json.event_id || null,
    order_id: $json.order_id || null,
    integration_status: 'rejected',
    error_type: $json.validation_result,
    missing_fields: $json.missing_fields || [],
    invalid_fields: $json.invalid_fields || [],
    message: 'Evento order.status_changed inválido'
  }
};
